298	/** Settle only a committed public message identity; acknowledgement stays pending.
299	 * Canonical history wins over the optimistic body and original local device. */
300	export function settleGroupSendIntents(
301	  set: Set,
302	  get: Get,
303	  status: AccountGroupOperationStatus,
304	): void {
305	  const lease = captureChatOwner(get);
306	  if (!lease.current() || get().myAccountId !== status.account_id) return;
307	  if (!["committed", "rejected", "cancelled"].includes(status.phase.kind))
308	    return;
309	  if (status.phase.kind === "committed" && !status.primary_event) return;
310	  const matches = Object.entries(get().intents).filter(
311	    ([, intent]) =>
312	      intent.operationId === status.id &&
313	      intent.conversation.kind === "channel" &&
314	      intent.conversation.id === status.group &&
315	      intent.payload.kind === status.kind,
316	  );
317	  for (const [clientId, intent] of matches) {
318	    if (!lease.current()) return;
319	    if (intent.message.id) continue;
320	    const key = convKey(intent.conversation);
321	    let next: ChatMessage | null;
322	    if (status.phase.kind === "committed") {
323	      const canonical = get().messages[key]?.find(
324	        (message) => message.id === status.primary_event,
325	      );
326	      const source = status.executions.find((execution) =>
327	        execution.committed_events.includes(status.primary_event!),
328	      );
329	      if (
330	        intent.payload.kind === "file" &&
331	        (!canonical?.file?.fileConv || canonical.metadataPending)
332	      )
333	        continue;
334	      if (!canonical && !source) continue;
335	      next = {
336	        ...(canonical ?? { ...intent.message, who: source!.device_id }),
337	        id: status.primary_event,
338	        clientId,
339	        pending: false,
340	        failed: false,
341	        failReason: undefined,
342	      };
343	    } else if (status.phase.kind === "cancelled") next = null;
344	    else
345	      next = {
346	        ...intent.message,
347	        pending: false,
348	        failed: true,
349	        failReason: "authorization",
350	      };
351	    if (!lease.current()) return;
352	    set((state) =>
353	      lease.current()
354	        ? completeSendIntentState(
355	            state,
356	            intent.conversation,
357	            clientId,
358	            next,
359	            Math.max(Date.now(), get().expiryNow ?? 0),
360	          )
361	        : {},
362	    );
