                .delete_unlocked("alice", ME, ME, false, || Ok(()))
                .is_err()
        );
        assert!(
            store
                .delete_unlocked("alice", "invalid", ME, false, || Ok(()))
                .is_err()
        );
        assert!(
            store
                .get(Some("alice"), "alice")
                .unwrap()
                .deleted
                .is_empty()
        );
        std::fs::create_dir_all(store.path("alice")).unwrap();
        assert!(
            store
                .delete_unlocked("alice", A, ME, false, || Ok(()))
                .is_err()
        );
    }

    #[test]
