+    ) -> Result<std::collections::HashSet<String>, super::NodeError> {
+        let mut associations = associations.into_iter();
+        let mut result = std::collections::HashSet::new();
+        loop {
+            let batch: Vec<_> = associations.by_ref().take(128).collect();
+            if batch.is_empty() {
